#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include "kernel.h"
#include <string>

static void check_fp32_contiguous_cuda(
    const torch::Tensor& tensor, const std::string& name) {
    TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
    TORCH_CHECK(
        tensor.dtype() == torch::kFloat32,
        name, " must have float32 dtype, got ", tensor.dtype());
    TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

// Destination-passing-style entry. definition.json declares:
//   x      : [batch_size, seq_len, intermediate_size] fp32
//   output : [batch_size, seq_len, intermediate_size] fp32 (DPS)
//
// intermediate_size is constant at 4096 per definition.json;
// batch_size and seq_len are variable.
void run(
    const torch::Tensor& x,
    torch::Tensor output
) {
    TORCH_CHECK(x.dim() == 3, "x must be 3D [batch, seq, intermediate]");
    TORCH_CHECK(output.dim() == 3, "output must be 3D");
    TORCH_CHECK(
        x.sizes() == output.sizes(),
        "output shape must match x");

    check_fp32_contiguous_cuda(x, "x");
    check_fp32_contiguous_cuda(output, "output");

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    problem_025_video_latent_gelu_launcher(x, output, stream);
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def(
        "run", &run,
        "FP32 GELU (tanh approximation) element-wise on video latent "
        "tensors. Destination-passing style; float4-vectorized "
        "load/store along the contiguous last dim.");
}

#include "kernel.h"
#include <cuda_runtime.h>

// FP32 GELU with tanh approximation:
//   output = 0.5 * x * (1 + tanh(sqrt(2/pi) * (x + 0.044715 * x^3)))
//
// Streams x and writes output via float4 vectorized loads/stores
// when the element count is a multiple of 4 and the tensor base
// pointer is 16-byte aligned (always true for ATen-allocated CUDA
// tensors). For the tail, a scalar fallback handles any remainder.
//
// Numerical contract: the reference uses ``torch.tanh`` (FP32
// math.tanh-style). ``tanhf`` matches the reference's tolerance
// (max_atol=1e-5, max_rtol=0.05 per the workload set).

namespace {

constexpr float kSqrt2OverPi = 0.7978845608028654f;
constexpr float kCoeff = 0.044715f;

__device__ __forceinline__ float gelu_tanh_approx_f(float x) {
    float inner = kSqrt2OverPi * (x + kCoeff * x * x * x);
    return 0.5f * x * (1.0f + tanhf(inner));
}

__global__ void problem_025_gelu_vec4_kernel(
    const float4* __restrict__ x,
    float4* __restrict__ output,
    int n_vec4) {

    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= n_vec4) {
        return;
    }
    float4 in = x[idx];
    float4 out;
    out.x = gelu_tanh_approx_f(in.x);
    out.y = gelu_tanh_approx_f(in.y);
    out.z = gelu_tanh_approx_f(in.z);
    out.w = gelu_tanh_approx_f(in.w);
    output[idx] = out;
}

__global__ void problem_025_gelu_tail_kernel(
    const float* __restrict__ x,
    float* __restrict__ output,
    int tail_start,
    int total) {

    const int idx = tail_start + blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) {
        return;
    }
    output[idx] = gelu_tanh_approx_f(x[idx]);
}

}  // namespace

void problem_025_video_latent_gelu_launcher(
    const torch::Tensor& x,
    torch::Tensor& output,
    cudaStream_t stream) {

    const int total = static_cast<int>(x.numel());
    const int n_vec4 = total / 4;
    const int tail_start = n_vec4 * 4;

    constexpr int BLOCK_THREADS = 256;

    if (n_vec4 > 0) {
        const int grid = (n_vec4 + BLOCK_THREADS - 1) / BLOCK_THREADS;
        problem_025_gelu_vec4_kernel<<<grid, BLOCK_THREADS, 0, stream>>>(
            reinterpret_cast<const float4*>(x.data_ptr<float>()),
            reinterpret_cast<float4*>(output.data_ptr<float>()),
            n_vec4);
    }
    if (tail_start < total) {
        const int remaining = total - tail_start;
        const int grid = (remaining + BLOCK_THREADS - 1) / BLOCK_THREADS;
        problem_025_gelu_tail_kernel<<<grid, BLOCK_THREADS, 0, stream>>>(
            x.data_ptr<float>(),
            output.data_ptr<float>(),
            tail_start,
            total);
    }
}

#pragma once

#ifndef PROBLEM_025_VIDEO_LATENT_GELU_ACTIVATION_KERNEL_H
#define PROBLEM_025_VIDEO_LATENT_GELU_ACTIVATION_KERNEL_H

#include <cuda_runtime.h>
#include <torch/extension.h>

// Host launcher for the FP32 GELU (tanh approximation) element-wise
// kernel. Input ``x`` is [batch_size, seq_len, intermediate_size]
// FP32 contiguous; ``output`` is pre-allocated with the same shape
// and dtype (destination-passing style). The kernel does no data
// rearrangement; it streams ``x`` once and writes ``output`` once.
void problem_025_video_latent_gelu_launcher(
    const torch::Tensor& x,
    torch::Tensor& output,
    cudaStream_t stream);

#endif  // PROBLEM_025_VIDEO_LATENT_GELU_ACTIVATION_KERNEL_H
